import React, { useState, useEffect } from 'react';
import { Row, Col, Card, Button, Spinner, Alert, Modal } from 'react-bootstrap';
import db from './db';
import { useNavigate } from 'react-router-dom';
import { useText } from '../contexts/TextContext';

function ResumeList({refreshData}) {
  const [resumes, setResumes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [resumeToDelete, setResumeToDelete] = useState(null);
  const navigate = useNavigate();
  const { text: t } = useText();
  
  useEffect(() => {
    const loadResumes = async () => {
      try {
        setLoading(true);
        const allResumes = await db.resumes.toArray();
        setResumes(allResumes);
      } catch (err) {
        setError(t.loadResumesError.replace('{error}', err.message));
      } finally {
        setLoading(false);
      }
    };

    loadResumes();
  }, [refreshData, t]);

  const handleDeleteClick = (id) => {
    setResumeToDelete(id);
    setShowDeleteModal(true);
  };

  const confirmDelete = async () => {
    try {
      await db.resumes.delete(resumeToDelete);
      setResumes(resumes.filter(resume => resume.id !== resumeToDelete));
      setShowDeleteModal(false);
    } catch (err) {
      setError(t.deleteResumeError.replace('{error}', err.message));
      setShowDeleteModal(false);
    }
  };

  const cancelDelete = () => {
    setResumeToDelete(null);
    setShowDeleteModal(false);
  };

  if (loading) {
    return (
      <div className="text-center my-5">
        <Spinner animation="border" role="status">
          <span className="visually-hidden">{t.loadingResumes}</span>
        </Spinner>
      </div>
    );
  }

  if (error) {
    return <Alert variant="danger">{error}</Alert>;
  }

  if (resumes.length === 0) {
    return (
      <Alert variant="info" className="mt-4">
        {t.noResumesFound}
      </Alert>
    );
  }

  return (
    <div className="mt-4">
      {/* Delete Confirmation Modal */}
      <Modal show={showDeleteModal} onHide={cancelDelete}>
        <Modal.Header closeButton>
          <Modal.Title>{t.deleteConfirmationTitle || "Confirm Deletion"}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {t.deleteConfirmationMessage || "Are you sure you want to delete this resume? This action cannot be undone."}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={cancelDelete}>
            {t.cancelButton || "Cancel"}
          </Button>
          <Button variant="danger" onClick={confirmDelete}>
            {t.deleteButton || "Delete"}
          </Button>
        </Modal.Footer>
      </Modal>

      <Row xs={1} md={2} lg={3} className="g-4">
        {resumes.map((resume) => (
          <Col key={resume.id}>
            <Card className="h-100">
              <Card.Body>
                <Card.Title>{resume.title}</Card.Title>
                <Card.Subtitle className="mb-2 text-muted">
                  {resume.topic}
                </Card.Subtitle>
              </Card.Body>
              <Card.Footer className="d-flex justify-content-between">
                <Button 
                  variant="outline-primary" 
                  size="sm"
                  onClick={() => navigate(`/resumes/edit/${resume.id}`)}
                >
                  {t.editButton}
                </Button>
                <Button
                  variant="outline-danger"
                  size="sm"
                  onClick={() => handleDeleteClick(resume.id)}
                >
                  {t.deleteButton}
                </Button>
              </Card.Footer>
            </Card>
          </Col>
        ))}
      </Row>
    </div>
  );
}

export default ResumeList;