import React, { useState } from 'react';
import { Card, Container, Button, Modal, Row, Col } from 'react-bootstrap';
import AddHeader from './AddHeader';
import ShowHeader from './ShowHeader';
import { useText } from '../../../contexts/TextContext';

function HeaderSection({ resumeId, header, refreshPage }) {
  const [showModal, setShowModal] = useState(false);
   const { text: t } = useText();

  return (
    <Container className="my-4">
      {/* Show Header Button (only if no header exists) */}
      {!header && (
        <Row className="mb-3">
          <Col>
            <Button 
              variant="primary" 
              onClick={() => setShowModal(true)}
              className="mb-3"
            >
              <i className="bi bi-plus-circle me-2"></i>
              {t.addHeaderTitle}
            </Button>
          </Col>
        </Row>
      )}

      {/* Display existing header */}
      {/* {JSON.stringify(header)} */}
      <ShowHeader header={header} />

      {/* Edit Button (if header exists) */}
      {header && (
        <Row>
          <Col>
            <Button 
              variant="outline-primary" 
              onClick={() => setShowModal(true)}
              size="sm"
            >
              <i className="bi bi-pencil me-1"></i>
              {t.editHeaderTitle}
            </Button>
          </Col>
        </Row>
      )}

      {/* Add/Edit Header Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>
            {header ? t.editHeaderTitle : t.addHeaderTitle}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <AddHeader 
            resumeId={resumeId} 
            existingHeader={header} 
            refreshPage={() => {
              refreshPage();
              setShowModal(false);
            }} 
          />
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            {t.closeButton}
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
}

export default HeaderSection;