// Database version upgrades
db.version(6).upgrade(trans => {
  // Create experiences table if not exists
  if (!trans.db.tables.find(t => t.name === 'experiences')) {
    trans.db.createObjectStore('experiences', {
      keyPath: 'id',
      autoIncrement: true
    });
    trans.experiences.createIndex('resumeId', 'resumeId');
  }
  
  // Create educations table if not exists
  if (!trans.db.tables.find(t => t.name === 'educations')) {
    trans.db.createObjectStore('educations', {
      keyPath: 'id',
      autoIncrement: true
    });
    trans.educations.createIndex('resumeId', 'resumeId');
  }

  // Create extraactivities table if not exists
  if (!trans.db.tables.find(t => t.name === 'extraactivities')) {
    trans.db.createObjectStore('extraactivities', {
      keyPath: 'id',
      autoIncrement: true
    });
    trans.extraactivities.createIndex('resumeId', 'resumeId');
  }

  // Create skills table if not exists
  if (!trans.db.tables.find(t => t.name === 'skills')) {
    trans.db.createObjectStore('skills', {
      keyPath: 'id',
      autoIncrement: true
    });
    trans.skills.createIndex('resumeId', 'resumeId');
  }

  // Create languages table if not exists
  if (!trans.db.tables.find(t => t.name === 'languages')) {
    trans.db.createObjectStore('languages', {
      keyPath: 'id',
      autoIncrement: true
    });
    trans.languages.createIndex('resumeId', 'resumeId');
  }

  // Create references table if not exists
  if (!trans.db.tables.find(t => t.name === 'references')) {
    trans.db.createObjectStore('references', {
      keyPath: 'id',
      autoIncrement: true
    });
    trans.references.createIndex('resumeId', 'resumeId');
  }
});

