db.exportResumeData = async function(resumeId) {
  return db.transaction('r', [
    db.resumes,
    db.headers,
    db.experiences,
    db.educations,
    db.extraactivities,
    db.skills,
    db.languages,
    db.references
  ], async () => {
    const resume = await db.resumes.get(parseInt(resumeId));
    if (!resume) {
      throw new Error(`Resume with ID ${resumeId} not found`);
    }

    // Get header data and exclude image_data
    const headerData = await db.headers.byResume(resumeId);
    const headerWithoutImage = headerData ? {
      ...headerData,
      image_data: undefined // Explicitly remove image_data
    } : null;

    return {
      resume,
      header: headerWithoutImage,
      experiences: await db.experiences.byResume(resumeId),
      educations: await db.educations.byResume(resumeId),
      extraactivities: await db.extraactivities.byResume(resumeId),
      skills: await db.skills.byResume(resumeId),
      languages: await db.languages.byResume(resumeId),
      references: await db.references.byResume(resumeId),
      exportedAt: new Date().toISOString()
    };
  });
};

/**
 * Import a complete resume with all related data
 * @param {Object} resumeData - The complete resume data to import
 * @param {boolean} [overwrite=false] - Whether to overwrite existing resume
 * @returns {Promise<number>} - A promise that resolves with the new resume ID
 */
db.importResumeData = async function(resumeData, overwrite = false) {
  return db.transaction('rw', [
    db.resumes,
    db.headers,
    db.experiences,
    db.educations,
    db.extraactivities,
    db.skills,
    db.languages,
    db.references
  ], async () => {
    // Remove the exportedAt field if it exists
    const { exportedAt, ...data } = resumeData;
    
    let resumeId;
    
    if (overwrite && data.resume.id) {
      // Update existing resume
      resumeId = data.resume.id+"";
      await db.resumes.update(parseInt(resumeId), data.resume);
      
      // Delete all related data first
      await Promise.all([
        db.headers.where('resumeId').equals(resumeId+"").delete(),
        db.experiences.where('resumeId').equals(resumeId+"").delete(),
        db.educations.where('resumeId').equals(resumeId+"").delete(),
        db.extraactivities.where('resumeId').equals(resumeId+"").delete(),
        db.skills.where('resumeId').equals(resumeId+"").delete(),
        db.languages.where('resumeId').equals(resumeId+"").delete(),
        db.references.where('resumeId').equals(resumeId+"").delete()
      ]);
    } else {
      // Create new resume
      delete data.resume.id; // Remove ID to create new record
      resumeId = await db.resumes.add(data.resume)+"";
    }
    
    // Add all related data with the new resumeId
    const promises = [];
    
    if (data.header) {
      delete data.header.id;
      promises.push(db.headers.add({ ...data.header, resumeId }));
    }
    
    if (data.experiences && data.experiences.length) {
      promises.push(
        db.experiences.bulkAdd(
          data.experiences.map(exp => {
            delete exp.id;
            return { ...exp, resumeId };
          })
        )
      );
    }
    
    if (data.educations && data.educations.length) {
      promises.push(
        db.educations.bulkAdd(
          data.educations.map(edu => {
            delete edu.id;
            return { ...edu, resumeId };
          })
        )
      );
    }
    
    if (data.extraactivities && data.extraactivities.length) {
      promises.push(
        db.extraactivities.bulkAdd(
          data.extraactivities.map(act => {
            delete act.id;
            return { ...act, resumeId };
          })
        )
      );
    }
    
    if (data.skills && data.skills.length) {
      promises.push(
        db.skills.bulkAdd(
          data.skills.map(skill => {
            delete skill.id;
            return { ...skill, resumeId };
          })
        )
      );
    }
    
    if (data.languages && data.languages.length) {
      promises.push(
        db.languages.bulkAdd(
          data.languages.map(lang => {
            delete lang.id;
            return { ...lang, resumeId };
          })
        )
      );
    }
    
    if (data.references && data.references.length) {
      promises.push(
        db.references.bulkAdd(
          data.references.map(ref => {
            delete ref.id;
            return { ...ref, resumeId };
          })
        )
      );
    }
    
    await Promise.all(promises);
    return resumeId;
  });
};


export default db;