import React, { useState } from 'react';
import {
    Card,
    ListGroup,
    Button,
    Modal,
    Toast,
    Badge,
    Container,
    Row,
    Col
} from 'react-bootstrap';
import db from '../../db';
import EditLanguage from './EditLanguage';
import { useText } from '../../../contexts/TextContext';

function ShowLanguages({ languages, resumeId, refreshPage }) {
    const { text: t,currentLanguage } = useText();

    const [showToast, setShowToast] = useState(false);
    const [toastMessage, setToastMessage] = useState('');
    const [toastVariant, setToastVariant] = useState('success');
    const [isEditModalOpen, setEditModalOpen] = useState(false);
    const [selectedLanguage, setSelectedLanguage] = useState(null);
    const [isDeleting, setIsDeleting] = useState(false);

    const handleEditOpen = (language) => {
        setSelectedLanguage(language);
        setEditModalOpen(true);
    };

    const handleEditClose = () => {
        setEditModalOpen(false);
        setSelectedLanguage(null);
    };

    const handleDeleteLanguage = async (languageId) => {
        if (window.confirm(t.deleteConfirmationLan)) {
            setIsDeleting(true);
            try {
                await db.languages.delete(languageId);

                setToastMessage(t.languageDeletedSuccess);
                setToastVariant('success');
                setShowToast(true);
            } catch (error) {
                console.error("Error deleting language:", error);
                setToastMessage(t.languageDeleteError);
                setToastVariant('danger');
                setShowToast(true);
            } finally {
               // setIsDeleting(false);
            }
            refreshPage()

        }
    };

    const getProficiencyVariant = (proficiency) => {
        switch (proficiency) {
            case 'Native': return 'success';
            case 'Fluent': return 'info';
            case 'Conversational': return 'warning';
            case 'Basic': return 'secondary';
            default: return 'light';
        }
    };

    return (
        <Container className="mt-4">
            <Card>
                <Card.Body>
                    <Card.Title className="mb-4">
                        {t.languagesTitle}
                        <Badge bg="secondary" className="ms-2">
                            {languages && languages.length}
                        </Badge>
                    </Card.Title>

                    {/* Toast Notification */}
                    <Toast
                        show={showToast}
                        onClose={() => setShowToast(false)}
                        delay={3000}
                        autohide
                        bg={toastVariant}
                        className="position-fixed top-0 end-0 m-3"
                    >
                        <Toast.Body className="text-white">
                            {toastMessage}
                        </Toast.Body>
                    </Toast>

                    {languages && languages.length > 0 ? (
                        <ListGroup variant="flush">
                            {languages.map(language => (
                                <ListGroup.Item key={language.id} className="mb-3 border rounded">
                                    <div className="d-flex justify-content-between align-items-start">
                                        <div>
                                            <h5 className="mb-1">
                                                {language.language}
                                                {language.certificate && (
                                                    <Badge bg="success" className="ms-2">
                                                        {t.certifiedBadge}
                                                    </Badge>
                                                )}
                                            </h5>
                                            {language.test && (
                                                <small className="text-muted">
                                                    {t.testLabel2} {language.test}
                                                </small>
                                            )}
                                        </div>
                                        <div>
                                            <Button
                                                variant="outline-primary"
                                                size="sm"
                                                className="me-2"
                                                onClick={() => handleEditOpen(language)}
                                            >
                                                {t.editButton}
                                            </Button>
                                            <Button
                                                variant="outline-danger"
                                                size="sm"
                                                onClick={() => handleDeleteLanguage(language.id)}
                                                disabled={isDeleting}
                                            >
                                                {isDeleting ? t.deletingText : t.deleteButton}
                                            </Button>
                                        </div>
                                    </div>

                                    <div className="mt-2">
                                        <div className="d-flex align-items-center">
                                            <span className="me-2">{t.proficiencyLabel2}</span>
                                            <Badge bg={getProficiencyVariant(language.proficiency)}>
                                              {language.proficiency ? t[language.proficiency.toLowerCase()] : t.notSpecified}
                                            </Badge>
                                        </div>
                                    </div>
                                </ListGroup.Item>
                            ))}
                        </ListGroup>
                    ) : (
                        <Card.Text className="text-muted">
                            {t.noLanguagesText}
                        </Card.Text>
                    )}

                    {/* Edit Modal */}
                    <Modal show={isEditModalOpen} onHide={handleEditClose} size="lg">
                        <Modal.Header closeButton>
                            <Modal.Title>{t.editLanguageTitle}</Modal.Title>
                        </Modal.Header>
                        <Modal.Body>
                            {selectedLanguage && (
                                <EditLanguage
                                    language={selectedLanguage}
                                    resumeId={resumeId}
                                    refreshPage={refreshPage}
                                />
                            )}
                        </Modal.Body>
                    </Modal>
                </Card.Body>
            </Card>
        </Container>
    );
}

export default ShowLanguages;