import React, { useState, useEffect } from 'react';
import { Button, Form, Card, Alert, Spinner, Toast, Row,Col } from 'react-bootstrap';
import db from '../../db';
import { useText } from '../../../contexts/TextContext';

function AddHeader({ resumeId, existingHeader, refreshPage }) {
    const { text: t } = useText();
    const [showToast, setShowToast] = useState(false);
    const [toastMessage, setToastMessage] = useState('');
    const [toastVariant, setToastVariant] = useState('success');
    const [isLoading, setIsLoading] = useState(false);

    const [formData, setFormData] = useState({
        image_url: '',
        professional_summary: '',
        phone: '',
        email: '',
        location: '',
        personal_site: '',
        name: '',
        professional_title: '',
        current_company: '',
        current_position: ''
    });

    // Initialize form with existing data if available
    useEffect(() => {
        if (existingHeader) {
            setFormData({
                image_url: existingHeader.image_url || '',
                professional_summary: existingHeader.professional_summary || '',
                phone: existingHeader.phone || '',
                email: existingHeader.email || '',
                location: existingHeader.location || '',
                personal_site: existingHeader.personal_site || '',
                name: existingHeader.name || '',
                professional_title: existingHeader.professional_title || '',
                current_company: existingHeader.current_company || '',
                current_position: existingHeader.current_position || ''
            });
        }
    }, [existingHeader]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsLoading(true);

        try {
            if (existingHeader) {
                // Update existing header
                await db.headers.update(existingHeader.id, {
                    ...formData,
                    updatedAt: new Date()
                });
                setToastMessage(t.headerUpdatedSuccess);
            } else {
                // Create new header
                await db.headers.add({
                    ...formData,
                    resumeId: resumeId,
                    createdAt: new Date(),
                    updatedAt: new Date()
                });
                setToastMessage(t.headerCreatedSuccess);
            }
            
            setToastVariant('success');
            setShowToast(true);
            refreshPage(); // Refresh parent component
        } catch (error) {
            console.error('Error saving header:', error);
            setToastMessage(t.headerSaveError);
            setToastVariant('danger');
            setShowToast(true);
        } finally {
            setIsLoading(false);
        }
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleImageUpload = (e) => {
        const file = e.target.files[0];
        if (!file) return;
      
        const reader = new FileReader();
        reader.onloadend = () => {
          setFormData(prev => ({
            ...prev,
            image_data: reader.result // base64 string
          }));
        };
        reader.readAsDataURL(file); // converts to base64
      };


    return (
        <Card className="mb-4">
            <Card.Body>
                <Card.Title>
                    {existingHeader ? t.editHeaderTitle : t.addHeaderTitle}
                </Card.Title>

                {/* Toast Notification */}
                <Toast 
                    show={showToast} 
                    onClose={() => setShowToast(false)}
                    delay={3000} 
                    autohide
                    bg={toastVariant}
                    className="position-fixed top-0 end-0 m-3"
                >
                    <Toast.Body className="text-white">
                        {toastMessage}
                    </Toast.Body>
                </Toast>

                <Form onSubmit={handleSubmit}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.uploadImageLabel}</Form.Label>
                  <Form.Control
                    type="file"
                    accept="image/*"
                    onChange={(e) => handleImageUpload(e)}
                  />
                </Form.Group>
                
                    <Form.Group className="mb-3">
                        <Form.Label>{t.professionalSummaryLabel}</Form.Label>
                        <Form.Control
                            as="textarea"
                            rows={3}
                            name="professional_summary"
                            value={formData.professional_summary}
                            onChange={handleChange}
                            required
                        />
                    </Form.Group>

                    <Row>
                        <Col md={6}>
                            <Form.Group className="mb-3">
                                <Form.Label>{t.nameLabel}</Form.Label>
                                <Form.Control
                                    type="text"
                                    name="name"
                                    value={formData.name}
                                    onChange={handleChange}
                                    required
                                />
                            </Form.Group>
                        </Col>
                        <Col md={6}>
                            <Form.Group className="mb-3">
                                <Form.Label>{t.professionalTitleLabel}</Form.Label>
                                <Form.Control
                                    type="text"
                                    name="professional_title"
                                    value={formData.professional_title}
                                    onChange={handleChange}
                                    required
                                />
                            </Form.Group>
                        </Col>
                    </Row>

                    <Row>
                        <Col md={6}>
                            <Form.Group className="mb-3">
                                <Form.Label>{t.emailLabel}</Form.Label>
                                <Form.Control
                                    type="email"
                                    name="email"
                                    value={formData.email}
                                    onChange={handleChange}
                                    required
                                />
                            </Form.Group>
                        </Col>
                        <Col md={6}>
                            <Form.Group className="mb-3">
                                <Form.Label>{t.phoneLabel}</Form.Label>
                                <Form.Control
                                    type="text"
                                    name="phone"
                                    value={formData.phone}
                                    onChange={handleChange}
                                />
                            </Form.Group>
                        </Col>
                    </Row>

                    <Row>
                        <Col md={6}>
                            <Form.Group className="mb-3">
                                <Form.Label>{t.locationLabel}</Form.Label>
                                <Form.Control
                                    type="text"
                                    name="location"
                                    value={formData.location}
                                    onChange={handleChange}
                                />
                            </Form.Group>
                        </Col>
                        <Col md={6}>
                            <Form.Group className="mb-3">
                                <Form.Label>{t.personalWebsiteLabel}</Form.Label>
                                <Form.Control
                                    type="text"
                                    name="personal_site"
                                    value={formData.personal_site}
                                    onChange={handleChange}
                                />
                            </Form.Group>
                        </Col>
                    </Row>

                    <Row>
                        <Col md={6}>
                            <Form.Group className="mb-3">
                                <Form.Label>{t.currentCompanyLabel}</Form.Label>
                                <Form.Control
                                    type="text"
                                    name="current_company"
                                    value={formData.current_company}
                                    onChange={handleChange}
                                />
                            </Form.Group>
                        </Col>
                        <Col md={6}>
                            <Form.Group className="mb-3">
                                <Form.Label>{t.currentPositionLabel}</Form.Label>
                                <Form.Control
                                    type="text"
                                    name="current_position"
                                    value={formData.current_position}
                                    onChange={handleChange}
                                />
                            </Form.Group>
                        </Col>
                    </Row>

                    <div className="d-grid gap-2">
                        <Button 
                            variant="primary" 
                            type="submit"
                            disabled={isLoading}
                        >
                            {isLoading ? (
                                <>
                                    <Spinner
                                        as="span"
                                        animation="border"
                                        size="sm"
                                        role="status"
                                        aria-hidden="true"
                                    />
                                    <span className="ms-2">{t.savingText}</span>
                                </>
                            ) : (
                                existingHeader ? t.updateHeaderButton : t.saveHeaderButton
                            )}
                        </Button>
                    </div>
                </Form>
            </Card.Body>
        </Card>
    );
}

export default AddHeader;