import { useState } from 'react';
import UploadResumeRawData from './UploadResumeRawData';
import DownloadResumeRawData from './DownloadResumeRawData';
import { useText } from '../../contexts/TextContext';
function ResumeDataManager({resumeId}) {
  const [uploadedResumeId, setUploadedResumeId] = useState(null);

  const handleUploadSuccess = (newResumeId) => {
    setUploadedResumeId(newResumeId);
  };

  return (
    <div className="container mt-4">
      <UploadResumeRawData onUploadSuccess={handleUploadSuccess} />

        <DownloadResumeRawData resumeId={resumeId} />

    </div>
  );
}

export default ResumeDataManager;