import React, { useState } from 'react';
import { Button, Modal, Form, Alert } from 'react-bootstrap';
import db from './db';
import ResumeList from './ResumeList';
import { useText } from '../contexts/TextContext';

function SaveResumeForm() {
  const [show, setShow] = useState(false);
  const [title, setTitle] = useState('');
  const [topic, setTopic] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [success, setSuccess] = useState(null);
  const [error, setError] = useState(null);
  const [refreshData, setRefreshData] = useState(true);
  const { text: t } = useText();

  const handleClose = () => {
    setShow(false);
    // Reset form when closing
    setTitle('');
    setTopic('');
    setError(null);
    setSuccess(null);
  };

  const handleShow = () => setShow(true);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSaving(true);
    setError(null);
    setSuccess(null);

    try {
      const id = await db.resumes.add({ title, topic });
      setSuccess(t.saveSuccess.replace('{id}', id));
      setRefreshData(!refreshData);
      // Don't clear fields immediately so user can see success message
    } catch (err) {
      setError(t.saveError.replace('{error}', err.message));
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <>
      {/* Trigger Button */}
      <Button variant="primary" onClick={handleShow}>
        {t.createResumeButton}
      </Button>

      {/* Modal */}
      <Modal show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>{t.saveNewResumeTitle}</Modal.Title>
        </Modal.Header>
        
        <Form onSubmit={handleSubmit}>
          <Modal.Body>
            {success && <Alert variant="success">{success}</Alert>}
            {error && <Alert variant="danger">{error}</Alert>}

            <Form.Group className="mb-3">
              <Form.Label>{t.titleLabel}</Form.Label>
              <Form.Control
                type="text"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder={t.titlePlaceholder}
                required
                disabled={isSaving || success}
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>{t.topicLabel}</Form.Label>
              <Form.Control
                type="text"
                value={topic}
                onChange={(e) => setTopic(e.target.value)}
                placeholder={t.topicPlaceholder}
                required
                disabled={isSaving || success}
              />
            </Form.Group>
          </Modal.Body>

          <Modal.Footer>
            <Button 
              variant="secondary" 
              onClick={handleClose}
              disabled={isSaving}
            >
              {t.closeButton}
            </Button>
            <Button 
              variant="primary" 
              type="submit"
              disabled={isSaving || success}
            >
              {isSaving ? t.savingText : t.saveButton}
            </Button>
          </Modal.Footer>
        </Form>
      </Modal>
      <ResumeList refreshData={refreshData}/>
    </>
  );
}

export default SaveResumeForm;