import React from 'react';
import { Container, Row, Col, Button } from 'react-bootstrap';
import { useText } from '../contexts/TextContext';
import { useNavigate } from 'react-router-dom';
import resumeData from './resumeData';
import PdfPreviewer from '../components/PDF/PdfPreviewer';

const LandingPage = () => {
  const { text: t, changeLanguage, currentLanguage } = useText();
  const navigate = useNavigate();

  // Flag icons can be emoji or you can use actual flag images
  const languageOptions = [
    { code: 'en', flag: '🇬🇧', name: 'English' },
    { code: 'es', flag: '🇪🇸', name: 'Español' },
    { code: 'zh', flag: '🇨🇳', name: '中文' }
  ];

  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      minHeight: '85vh'
    }}>
      {/* Main content that will grow to push footer down */}
      <div style={{ flex: 1 }}>
        {/* Hero Section */}
        <div className="bg-light py-5 text-center">
          <Container>
            <h1 className="display-4">{t.heroTitle}</h1>
            <p className="lead">{t.heroSubtitle} {t.createdBy}</p>
            <Button 
              variant="primary" 
              size="lg" 
              className="me-3"
              onClick={() => navigate('/build')}
            >
              {t.getStarted}
            </Button>
            
            {/* Language Selector */}
            <div className="mt-3">
              {languageOptions.map((lang) => (
                <Button
                  key={lang.code}
                  variant={currentLanguage === lang.code ? 'primary' : 'outline-secondary'}
                  className="me-2"
                  onClick={() => changeLanguage(lang.code)}
                  title={lang.name}
                >
                  {lang.flag} {lang.name}
                </Button>
              ))}
            </div>
          </Container>
        </div>

        {/* Features Section */}
        <Container className="text-center my-5">
          <h2 className="mb-4">{t.featuresTitle}</h2>
          <Row>
            <Col md={4}><p>{t.feature1}</p></Col>
            <Col md={4}><p>{t.feature2}</p></Col>
            <Col md={4}><p>{t.feature3}</p></Col>
          </Row>
        </Container>
      </div>
      <PdfPreviewer
                            t={t}
                            key={"main_tpg"}
                            header={resumeData.header}
                            experiences={resumeData.experiences}
                            skills={resumeData.skills}
                            education={resumeData.educations}
                            imgURL={null}
                            references={resumeData.references}
                            extraactivities={resumeData.extraactivities}
                            languages={resumeData.languages} 
        />

      {/* Footer - will stay at bottom */}
      <footer className="bg-dark text-white text-center py-3 mt-auto">
        {t.footer}
      </footer>
    </div>
  );
};

export default LandingPage;