import React, { useState } from 'react';
import { Card, Container, Button, Modal, Row, Col } from 'react-bootstrap';
import ShowLanguages from './ShowLanguage';
import AddLanguage from './AddLanguage';
import { useText } from '../../../contexts/TextContext';

function LanguageSection({ resumeId, languages, refreshPage }) {
  const { text: t } = useText();
  const [showModal, setShowModal] = useState(false);

  return (
    <Container className="my-4">
      {/* Show Add Button (only if no languages exist) */}
      {!languages && (
        <Row className="mb-3">
          <Col>
            <Button 
              variant="primary" 
              onClick={() => setShowModal(true)}
              className="mb-3"
            >
              <i className="bi bi-plus-circle me-2"></i>
              {t.addLanguageButton}
            </Button>
          </Col>
        </Row>
      )}

      {/* Display existing language entries */}
      <ShowLanguages languages={languages} resumeId={resumeId} refreshPage={refreshPage} />

      {/* Add New Button (if language entries exist) */}
      {languages && (
        <Row>
          <Col>
            <Button 
              variant="outline-primary" 
              onClick={() => setShowModal(true)}
              size="sm"
              className="mt-2"
            >
              <i className="bi bi-plus-circle me-1"></i>
              {t.addLanguageTitle}
            </Button>
          </Col>
        </Row>
      )}

      {/* Add Language Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>
            {t.addLanguageButton}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <AddLanguage 
            resumeId={resumeId} 
            refreshPage={refreshPage}
          />
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            {t.closeButton}
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
}

export default LanguageSection;