import React from 'react';
import { Document, Page, Text, View, StyleSheet, Image } from '@react-pdf/renderer';

const styles = StyleSheet.create({
  page: {
    padding: 40,
    fontSize: 11,
    lineHeight: 1.4,
    fontFamily: 'Helvetica',
    color: '#333'
  },
  header: {
    marginBottom: 20,
    borderBottom: '1px solid #eee',
    paddingBottom: 20
  },
  name: {
    fontSize: 24,
    fontWeight: 'bold',
    color: '#2c3e50',
    marginBottom: 5
  },
  title: {
    fontSize: 14,
    color: '#7f8c8d',
    marginBottom: 10
  },
  contactInfo: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    width: '100%'
  },
  contactItem: {
    fontSize: 10,
    color: '#7f8c8d'
  },
  section: {
    marginBottom: 15
  },
  sectionTitle: {
    fontSize: 14,
    fontWeight: 'bold',
    color: '#2c3e50',
    marginBottom: 10,
    borderBottom: '1px solid #eee',
    paddingBottom: 3
  },
  job: {
    marginBottom: 15
  },
  jobHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 5
  },
  jobTitle: {
    fontSize: 12,
    fontWeight: 'bold',
    color: '#2c3e50'
  },
  company: {
    fontSize: 12,
    fontWeight: 'bold',
    color: '#3498db'
  },
  date: {
    fontSize: 10,
    color: '#7f8c8d'
  },
  jobDescription: {
    fontSize: 10,
    textAlign: 'justify'
  },
  educationItem: {
    marginBottom: 10
  },
  degree: {
    fontSize: 12,
    fontWeight: 'bold'
  },
  institution: {
    fontSize: 11,
    fontStyle: 'italic'
  },
  skillsContainer: {
    flexDirection: 'row',
    flexWrap: 'wrap'
  },
  skillItem: {
    width: '50%',
    marginBottom: 5
  },
  referenceItem: {
    width: '48%',
    marginBottom: 10
  },
  referenceName: {
    fontSize: 11,
    fontWeight: 'bold'
  },
  referencePosition: {
    fontSize: 10,
    fontStyle: 'italic'
  },
  referenceContact: {
    fontSize: 9,
    color: '#7f8c8d'
  }
});

const MyPdfDocument_2 = React.memo(({ t, header, experiences, skills, education, references, extraactivities, languages }) => {
  return (
    <Document>
      <Page size="A4" style={styles.page}>
        {/* Header */}
        <View style={styles.header}>
          <Text style={styles.name}>{header?.name}</Text>
          <Text style={styles.title}>{header?.current_position || header?.professional_title}</Text>
          
          <View style={styles.contactInfo}>
            {header?.phone && <Text style={styles.contactItem}>{header.phone}</Text>}
            {header?.email && <Text style={styles.contactItem}>{header.email}</Text>}
            {header?.location && <Text style={styles.contactItem}>{header.location}</Text>}
            {header?.personal_site && <Text style={styles.contactItem}>{header.personal_site}</Text>}
          </View>
        </View>

        {/* Summary */}
        {header?.professional_summary && (
          <View style={styles.section}>
            <Text style={styles.sectionTitle}>{t.profileTitle}</Text>
            <Text style={styles.jobDescription}>{header.professional_summary}</Text>
          </View>
        )}

        {/* Experience */}
        {experiences && experiences.length > 0 && (
          <View style={styles.section}>
            <Text style={styles.sectionTitle}>{t.workExperienceTitle}</Text>
            {experiences.map((exp, index) => (
              <View key={index} style={styles.job}>
                <View style={styles.jobHeader}>
                  <View>
                    <Text style={styles.jobTitle}>{exp.job_title}</Text>
                    <Text style={styles.company}>{exp.company_name} | {exp.place}</Text>
                  </View>
                  <Text style={styles.date}>
                    {exp.initial_date} - {exp.current ? t.presentText : exp.end_date}
                  </Text>
                </View>
                <Text style={styles.jobDescription}>{exp.description}</Text>
              </View>
            ))}
          </View>
        )}

        {/* Education */}
        {education && education.length > 0 && (
          <View style={styles.section}>
            <Text style={styles.sectionTitle}>{t.sectionEducation}</Text>
            {education.map((edu, index) => (
              <View key={index} style={styles.educationItem}>
                <Text style={styles.degree}>{edu.degree}</Text>
                <Text style={styles.institution}>{edu.institution}</Text>
                <Text style={styles.date}>{edu.graduation_date?.split('-')[0]}</Text>
              </View>
            ))}
          </View>
        )}

        {/* Skills */}
        {skills && skills.length > 0 && (
          <View style={styles.section}>
            <Text style={styles.sectionTitle}>{t.skillsTitle}</Text>
            <View style={styles.skillsContainer}>
              {skills.map((skill, index) => (
                <View key={index} style={styles.skillItem}>
                  <Text>• {skill.skill_name} {skill.certificate && '(Certified)'}</Text>
                </View>
              ))}
            </View>
          </View>
        )}

        {/* Languages */}
        {languages && languages.length > 0 && (
          <View style={styles.section}>
            <Text style={styles.sectionTitle}>{t.languagesTitle}</Text>
            <View style={styles.skillsContainer}>
              {languages.map((lang, index) => (
                <View key={index} style={styles.skillItem}>
                  <Text>• {lang.language} {lang.test && `(${lang.test})`}</Text>
                </View>
              ))}
            </View>
          </View>
        )}

        {/* Experience */}
        {extraactivities && extraactivities.length > 0 && (
          <View style={styles.section}>
            <Text style={styles.sectionTitle}>{t.extraActivitiesTitle}</Text>
            {extraactivities.map((exp, index) => (
              <View key={index} style={styles.job}>
                <View style={styles.jobHeader}>
                  <View>
                    <Text style={styles.jobTitle}>{exp.job_title}</Text>
                    <Text style={styles.company}>{exp.company_name} | {exp.place}</Text>
                  </View>
                  <Text style={styles.date}>
                    {exp.initial_date} - {exp.current ? t.presentText : exp.end_date}
                  </Text>
                </View>
                <Text style={styles.jobDescription}>{exp.description}</Text>
              </View>
            ))}
          </View>
        )}
        {/* References */}
        {references && references.length > 0 && (
          <View style={styles.section}>
            <Text style={styles.sectionTitle}>{t.referencesTitle}</Text>
            <View style={{ flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'space-between' }}>
              {references.map((ref, index) => (
                <View key={index} style={styles.referenceItem}>
                  <Text style={styles.referenceName}>{ref.name} {ref.last_name}</Text>
                  <Text style={styles.referencePosition}>{ref.position}, {ref.company_name}</Text>
                  <Text style={styles.referenceContact}>{t.phoneLabel}: {ref.phone}</Text>
                  <Text style={styles.referenceContact}>{t.emailLabel}: {ref.email}</Text>
                </View>
              ))}
            </View>
          </View>
        )}


      </Page>
    </Document>
  );
});

export default MyPdfDocument_2;