import React, { useState } from 'react';
import db from '../db';
import { Button, Form, Alert, Spinner, Toast, Card } from 'react-bootstrap';
import { useText } from '../../contexts/TextContext';

const UploadResumeRawData = ({ onUploadSuccess, resumeId }) => {
  const { text: t } = useText();
  const [jsonInput, setJsonInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastVariant, setToastVariant] = useState('success');
  const [validationError, setValidationError] = useState('');

  const showToastMessage = (message, variant = 'success') => {
    setToastMessage(message);
    setToastVariant(variant);
    setShowToast(true);
    setTimeout(() => setShowToast(false), 3000);
  };

  const handleJsonChange = (e) => {
    setJsonInput(e.target.value);
    setValidationError('');
  };

  const validateJson = (jsonString) => {
    try {
      const data = JSON.parse(jsonString);
      
      // Basic validation for required resume fields
      if (!data.resume || typeof data.resume !== 'object') {
        throw new Error('Invalid resume data format. Missing "resume" object.');
      }
      
      return data;
    } catch (error) {
      throw new Error(`Invalid JSON: ${error.message}`);
    }
  };

  const handleUpload = async () => {
    if (!jsonInput.trim()) {
      setValidationError(t.PleasePasteJSONDataBeforeUploading);
      return;
    }

    setIsLoading(true);
    setValidationError('');

    try {
      const parsedData = validateJson(jsonInput);
      const newResumeId = await db.importResumeData(parsedData, true);
      
      showToastMessage('Resume uploaded successfully!');
      setJsonInput(''); // Clear the input after successful upload
      
      if (onUploadSuccess) {
        onUploadSuccess(newResumeId); // Notify parent component
      }
    } catch (error) {
      console.error('Upload error:', error);
      setValidationError(error.message);
      showToastMessage(t.FailedToUploadResumeData, 'danger');
    } finally {
      setIsLoading(false);
    }
  };

  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const content = event.target.result;
        validateJson(content); // Validate before setting
        setJsonInput(content);
        setValidationError('');
      } catch (error) {
        setValidationError(error.message);
      }
    };
    reader.onerror = () => {
      setValidationError(t.FailedToReadFile);
    };
    reader.readAsText(file);
  };

  return (
    <Card className="p-3 mb-4">
      <Card.Body>
        <Card.Title className="mb-3">{t.UploadResumeData}</Card.Title>
        
        <Form.Group controlId="resumeJsonUpload" className="mb-3">
          <Form.Label>{t.PasteJSONDataOrUploadAFile}</Form.Label>
          <Form.Control
            as="textarea"
            rows={10}
            value={jsonInput}
            onChange={handleJsonChange}
            placeholder={t.PasteYourResumeJSONDataHere}
            style={{ fontFamily: 'monospace' }}
            disabled={isLoading}
          />
        </Form.Group>

        <div className="mb-3">
          <Form.Label>{t.OrUploadAJSONFile}</Form.Label>
          <Form.Control 
            type="file" 
            accept=".json,application/json" 
            onChange={handleFileUpload}
            disabled={isLoading}
          />
        </div>

        {validationError && (
          <Alert variant="danger" className="mb-3">
            {validationError}
          </Alert>
        )}

        <div className="d-flex gap-2">
          <Button
            variant="primary"
            onClick={handleUpload}
            disabled={!jsonInput || isLoading}
          >
            {isLoading ? (
              <>
                <Spinner
                  as="span"
                  animation="border"
                  size="sm"
                  role="status"
                  aria-hidden="true"
                  className="me-2"
                />
               {t.Uploading}
              </>
            ) : (
              t.UploadResumeData
            )}
          </Button>

          <Button
            variant="outline-secondary"
            onClick={() => setJsonInput('')}
            disabled={!jsonInput || isLoading}
          >
            {t.Clear}
          </Button>
        </div>
      </Card.Body>

      {/* Toast notification */}
      <div style={{ position: 'fixed', top: 20, right: 20, zIndex: 9999 }}>
        <Toast 
          show={showToast} 
          onClose={() => setShowToast(false)}
          delay={3000} 
          autohide
          bg={toastVariant}
        >
          <Toast.Body className="text-white">
            {toastMessage}
          </Toast.Body>
        </Toast>
      </div>
    </Card>
  );
};

export default UploadResumeRawData;