import React, { useState } from 'react';
import { Card, Container, Button, Modal, Row, Col } from 'react-bootstrap';
import ShowReferences from './ShowReference';
import AddReference from './AddReference';
import { useText } from '../../../contexts/TextContext';

function ReferenceSection({ resumeId, references, refreshPage }) {
  const { text: t } = useText();
  const [showModal, setShowModal] = useState(false);

  return (
    <Container className="my-4">
      {/* Show Add Button (only if no references exist) */}
      {!references && (
        <Row className="mb-3">
          <Col>
            <Button 
              variant="primary" 
              onClick={() => setShowModal(true)}
              className="mb-3"
            >
              <i className="bi bi-plus-circle me-2"></i>
              {t.addReferenceButton}
            </Button>
          </Col>
        </Row>
      )}

      {/* Display existing references */}
      <ShowReferences references={references} resumeId={resumeId} refreshPage={refreshPage} />

      {/* Add Reference Button (if references exist) */}
      {references && (
        <Row>
          <Col>
            <Button 
              variant="outline-primary" 
              onClick={() => setShowModal(true)}
              size="sm"
            >
              <i className="bi bi-plus-circle me-1"></i>
              {t.addReferenceButton}
            </Button>
          </Col>
        </Row>
      )}

      {/* Add Reference Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>
            {t.addReferenceButton}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <AddReference 
            resumeId={resumeId} 
            refreshPage={refreshPage}
          />
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            {t.closeButton}
          </Button>
        </Modal.Footer>
      </Modal>
    </Container>
  );
}

export default ReferenceSection;