import React from 'react';
import { PDFViewer, PDFDownloadLink } from '@react-pdf/renderer';

import MyPdfDocument_5 from './MyPdfDocument_5';

const PdfPreviewer_5 = ({t, header, experiences,skills, education, imgURL, references,extraactivities,languages }) => {
    return (
        <div>
            <h2>PDF Preview</h2>
            <PDFViewer style={{ width: '100%', height: '500px' }}>
                <MyPdfDocument_5  t={t}  extraactivities={extraactivities} languages={languages} references={references} imgURL={imgURL} header={header} experiences={experiences} skills={skills} education={education}/>
            </PDFViewer>

            <PDFDownloadLink
                document={<MyPdfDocument_5 t={t} extraactivities={extraactivities} languages={languages} imgURL={imgURL} references={references} header={header} experiences={experiences}  skills={skills} education={education}/>}
                fileName="resume.pdf"
            >
                <button style={{ padding: '10px', backgroundColor: 'blue', color: 'white' }}>
                    Download PDF
                </button>
            </PDFDownloadLink>
        </div>
    );
};

export default PdfPreviewer_5;