import React, { useState } from 'react';
import { 
  Button, 
  Form, 
  Card, 
  Toast, 
  Row, 
  Col,
  FormCheck,
  Container
} from 'react-bootstrap';
import db from '../../db';
import { useText } from '../../../contexts/TextContext';

function AddEducation({ resumeId, refreshPage }) {
  const { text: t } = useText();
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastVariant, setToastVariant] = useState('success');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState({
    initial_date: '',
    graduation_date: '',
    degree: '',
    institution: '',
    country: '',
    place: '',
    description: ''
  });

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      // Add education using Dexie
      await db.educations.addEducation(resumeId, formData);
      
      setToastMessage(t.educationAddedSuccess);
      setToastVariant('success');
      setShowToast(true);
      
      // Reset form
      setFormData({
        initial_date: '',
        graduation_date: '',
        degree: '',
        institution: '',
        country: '',
        place: '',
        description: ''
      });

      refreshPage();
    } catch (error) {
      console.error('Error adding education:', error);
      setToastMessage(t.educationAddError);
      setToastVariant('danger');
      setShowToast(true);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Container className="mt-4">
      <Card>
        <Card.Body>
          <Card.Title>{t.addEducationTitle}</Card.Title>
          
          {/* Toast Notification */}
          <Toast 
            show={showToast} 
            onClose={() => setShowToast(false)}
            delay={3000} 
            autohide
            bg={toastVariant}
            className="position-fixed top-0 end-0 m-3"
          >
            <Toast.Body className="text-white">
              {toastMessage}
            </Toast.Body>
          </Toast>

          <Form onSubmit={handleSubmit}>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.startDateLabel}</Form.Label>
                  <Form.Control
                    type="date"
                    name="initial_date"
                    value={formData.initial_date}
                    onChange={handleChange}
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.graduationDateLabel}</Form.Label>
                  <Form.Control
                    type="date"
                    name="graduation_date"
                    value={formData.graduation_date}
                    onChange={handleChange}
                  />
                </Form.Group>
              </Col>
            </Row>

            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.degreeLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="degree"
                    value={formData.degree}
                    onChange={handleChange}
                    placeholder={t.degreePlaceholder}
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.institutionLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="institution"
                    value={formData.institution}
                    onChange={handleChange}
                    placeholder={t.institutionPlaceholder}
                    required
                  />
                </Form.Group>
              </Col>
            </Row>

            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.countryLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="country"
                    value={formData.country}
                    onChange={handleChange}
                    placeholder={t.countryPlaceholder}
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>{t.cityPlaceLabel}</Form.Label>
                  <Form.Control
                    type="text"
                    name="place"
                    value={formData.place}
                    onChange={handleChange}
                    placeholder={t.cityPlaceholder}
                  />
                </Form.Group>
              </Col>
            </Row>

            <Form.Group className="mb-3">
              <Form.Label>{t.descriptionLabel}</Form.Label>
              <Form.Control
                as="textarea"
                rows={3}
                name="description"
                value={formData.description}
                onChange={handleChange}
                placeholder={t.descriptionPlaceholder}
              />
            </Form.Group>

            <div className="d-grid">
              <Button 
                variant="primary" 
                type="submit"
                disabled={isSubmitting}
              >
                {isSubmitting ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                    {t.addingText}
                  </>
                ) : t.addEducationButton}
              </Button>
            </div>
          </Form>
        </Card.Body>
      </Card>
    </Container>
  );
}

export default AddEducation;