import React, { useState, useEffect } from 'react';
import db from '../db';
import { Button, Form, Alert, Spinner, Toast } from 'react-bootstrap';
import { useText } from '../../contexts/TextContext';

const DownloadResumeRawData = ({ resumeId }) => {
  const { text: t } = useText();
  const [jsonData, setJsonData] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastVariant, setToastVariant] = useState('success');

  // Fetch resume data when component mounts or resumeId changes
  useEffect(() => {
    const fetchResumeData = async () => {
      setIsLoading(true);
      try {
        const data = await db.exportResumeData(resumeId);
        const formattedJson = JSON.stringify(data, null, 2);
        setJsonData(formattedJson);
      } catch (error) {
        console.error('Error fetching resume data:', error);
        showToastMessage('Failed to load resume data. Please try again.'+error, 'danger');
      } finally {
        setIsLoading(false);
      }
    };

    if (resumeId) {
      fetchResumeData();
    }
  }, [resumeId]);

  const showToastMessage = (message, variant = 'success') => {
    setToastMessage(message);
    setToastVariant(variant);
    setShowToast(true);
    setTimeout(() => setShowToast(false), 3000);
  };

  const handleDownload = () => {
    if (!jsonData) return;

    try {
      // Get resume title from the JSON data or use a default name
      const data = JSON.parse(jsonData);
      const resumeTitle = data?.resume?.title || 'resume';
      const fileName = `resume_${resumeTitle.replace(/\s+/g, '_')}_${resumeId}.json`;

      // Create download link
      const blob = new Blob([jsonData], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      showToastMessage(t.ResumeDataDownloadedSuccessfully);
    } catch (error) {
      console.error('Error downloading file:', error);
      showToastMessage(t.FailedToDownloadResumeData, 'danger');
    }
  };

  const handleCopyToClipboard = () => {
    if (!jsonData) return;

    navigator.clipboard.writeText(jsonData)
      .then(() => {
        showToastMessage('Resume data copied to clipboard!');
      })
      .catch((err) => {
        console.error('Failed to copy:', err);
        showToastMessage(t.FailedToCopyToClipboard, 'danger');
      });
  };

  return (
    <div className="p-3 border rounded">
      <div className="mb-3">
        <h4>{t.ResumeRawData} (ID: {resumeId})</h4>
        <p className="text-muted">
          {t.ViewCopyOrDownloadCompleteResumeData}
        </p>
      </div>

      {isLoading ? (
        <div className="text-center my-4">
          <Spinner animation="border" role="status">
            <span className="visually-hidden">{t.loadingResumes}</span>
          </Spinner>
          <p className="mt-2">{t.LoadingResumeData}</p>
        </div>
      ) : (
        <>
          <Form.Group controlId="resumeJsonData" className="mb-3">
            <Form.Control
              as="textarea"
              rows={10}
              value={jsonData}
              readOnly
              placeholder={jsonData ? '' : t.NoDataAvailable}
              style={{ fontFamily: 'monospace' }}
            />
          </Form.Group>

          <div className="d-flex gap-2">
            <Button
              variant="primary"
              onClick={handleDownload}
              disabled={!jsonData}
            >
              {t.DownloadJSON}
            </Button>

            <Button
              variant="outline-secondary"
              onClick={handleCopyToClipboard}
              disabled={!jsonData}
            >
              {t.CopyToClipboard}
            </Button>
          </div>
        </>
      )}

      {/* Toast notification */}
      <div style={{ position: 'fixed', top: 20, right: 20, zIndex: 9999 }}>
        <Toast 
          show={showToast} 
          onClose={() => setShowToast(false)}
          delay={3000} 
          autohide
          bg={toastVariant}
        >
          <Toast.Body className="text-white">
            {toastMessage}
          </Toast.Body>
        </Toast>
      </div>
    </div>
  );
};

export default DownloadResumeRawData;