import React from 'react';
import { Container, Row, Col, Button } from 'react-bootstrap';
import { useText } from '../../contexts/TextContext';

const sections = [
  'Header',
  'Experience',
  'ExtraActivities',
  'Skills',
  'Education',
  'Languages',
  'References',
  'RawData',
];

function MenuSection({ selectedSection, setSelectedSection }) {
  const { text: t } = useText();

  // Translation mapping for section names
  const sectionTranslations = {
    Header: t.sectionHeader || 'Header',
    Experience: t.sectionExperience || 'Experience',
    ExtraActivities: t.sectionExtraActivities || 'Extra Activities',
    Skills: t.sectionSkills || 'Skills',
    Education: t.sectionEducation || 'Education',
    Languages: t.sectionLanguages || 'Languages',
    References: t.sectionReferences || 'References',
    RawData: t.rawData || 'Raw Data',
  };

  return (
    <Container className="p-0">
      <Row xs={2} sm={2} md={4} className="g-2">
        {sections.map((section) => (
          <Col key={section}>
            <Button
              variant={selectedSection === section ? 'primary' : 'outline-primary'}
              onClick={() => setSelectedSection(section)}
              className="w-100 text-truncate"
              size="sm"
            >
              {sectionTranslations[section]}
            </Button>
          </Col>
        ))}
      </Row>
    </Container>
  );
}

export default MenuSection;